paragraph", "content": [{"type": "text", "text": "百化分时分数记错"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分数比较方向搞反"}]}]}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#eff6ff", "borderColor": "#3b82f6", "icon": "📊"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "刷题建议：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "简单计算的核心是\"能估就不精算\"。截位直除是最常用的速算方法。"}]}]}]}$$ AS jsonb), NULL, '资料分析-简单计算的核心知识点和解题方法。', category_node.id, CAST('["资料分析", "简单计算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_basic_calculation", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
